--
-- Structure for view `dashboard_aggregates_view`
--
DROP TABLE IF EXISTS `dashboard_aggregates_view`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `dashboard_aggregates_view`  AS SELECT row_number() over () AS `id`, `unified_data`.`graph_type` AS `graph_type`, `unified_data`.`category_number` AS `category_number`, `unified_data`.`category_text` AS `category_text`, `unified_data`.`value` AS `value` FROM (select 'Count by rank' collate utf8mb4_unicode_ci AS `graph_type`,NULL AS `category_number`,`personal_information_tbl`.`rank` AS `category_text`,count(0) AS `value` from `personal_information_tbl` group by `personal_information_tbl`.`rank` union all select 'Count by unit' collate utf8mb4_unicode_ci AS `graph_type`,`personal_information_tbl`.`unit` AS `category_number`,NULL AS `category_text`,count(0) AS `value` from `personal_information_tbl` group by `personal_information_tbl`.`unit` union all select 'Gender distribution' collate utf8mb4_unicode_ci AS `graph_type`,case `personal_information_tbl`.`sex` when 1 then 1 when 2 then 2 else 0 end AS `category_number`,NULL AS `category_text`,count(0) AS `value` from `personal_information_tbl` group by `personal_information_tbl`.`sex` union all select 'Civil status' collate utf8mb4_unicode_ci AS `graph_type`,`personal_information_tbl`.`civil_status` AS `category_number`,NULL AS `category_text`,count(0) AS `value` from `personal_information_tbl` group by `personal_information_tbl`.`civil_status` union all select 'Entry year trend' collate utf8mb4_unicode_ci AS `graph_type`,year(str_to_date(`personal_information_tbl`.`date_enter_military_service`,'%Y-%m-%d')) AS `category_number`,NULL AS `category_text`,count(0) AS `value` from `personal_information_tbl` where `personal_information_tbl`.`date_enter_military_service` is not null group by year(str_to_date(`personal_information_tbl`.`date_enter_military_service`,'%Y-%m-%d')) union all select 'Regional distribution' collate utf8mb4_unicode_ci AS `graph_type`,NULL AS `category_number`,`personal_information_tbl`.`region` AS `category_text`,count(0) AS `value` from `personal_information_tbl` group by `personal_information_tbl`.`region` union all select 'Blood type distribution' collate utf8mb4_unicode_ci AS `graph_type`,`personal_information_tbl`.`blood_type` AS `category_number`,NULL AS `category_text`,count(0) AS `value` from `personal_information_tbl` group by `personal_information_tbl`.`blood_type` union all select 'Age groups' collate utf8mb4_unicode_ci AS `graph_type`,floor(timestampdiff(YEAR,str_to_date(`personal_information_tbl`.`birthdate`,'%Y-%m-%d'),curdate()) / 10) * 10 AS `category_number`,NULL AS `category_text`,count(0) AS `value` from `personal_information_tbl` where `personal_information_tbl`.`birthdate` is not null group by floor(timestampdiff(YEAR,str_to_date(`personal_information_tbl`.`birthdate`,'%Y-%m-%d'),curdate()) / 10) union all select 'Specializations' collate utf8mb4_unicode_ci AS `graph_type`,NULL AS `category_number`,`personal_information_tbl`.`staff_specialization` AS `category_text`,count(0) AS `value` from `personal_information_tbl` where `personal_information_tbl`.`staff_specialization` is not null group by `personal_information_tbl`.`staff_specialization` union all select 'Specializations' collate utf8mb4_unicode_ci AS `graph_type`,NULL AS `category_number`,`personal_information_tbl`.`sub_specialization` AS `category_text`,count(0) AS `value` from `personal_information_tbl` where `personal_information_tbl`.`sub_specialization` is not null group by `personal_information_tbl`.`sub_specialization` union all select 'Retirement planning' collate utf8mb4_unicode_ci AS `graph_type`,NULL AS `category_number`,coalesce(`personal_information_tbl`.`status_definition_category`,'Active') AS `category_text`,count(0) AS `value` from `personal_information_tbl` group by coalesce(`personal_information_tbl`.`status_definition_category`,'Active')) AS `unified_data` ;

