--
-- Structure for view `personal_status_view`
--
DROP TABLE IF EXISTS `personal_status_view`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `personal_status_view`  AS SELECT `p`.`id` AS `id`, `p`.`firstname` AS `firstname`, CASE WHEN `r`.`date_of_retirement` is not null AND `r`.`date_of_retirement` >= curdate() THEN 'due for retirement' WHEN `r`.`date_of_retirement` is not null AND `r`.`date_of_retirement` < curdate() THEN 'retired' WHEN `latest_assign`.`unit` is not null AND `latest_assign`.`unit` <> 'NISF' THEN 'relieved' WHEN `designation_counts`.`designation_count` = 1 AND lcase(trim(`designation_counts`.`designation`)) = 'newly aboard' THEN 'newly aboard' WHEN `p`.`status_definition_category` is not null AND trim(`p`.`status_definition_category`) <> '' THEN `p`.`status_definition_category` ELSE 'active' END AS `status_definition_category`, CASE WHEN `p`.`sex` = 2 AND `p`.`date_enter_military_service` between '2008-12-17' and '2016-12-01' THEN CASE WHEN `p`.`fos_rating` in (2,3,4,5,23,24,25,26,27,28) THEN CASE `p`.`rank_code` WHEN 'E-1' THEN 'None' WHEN 'E-2' THEN 'No Required Duty' WHEN 'E-3' THEN '18 Months Sea Duty' WHEN 'E-4' THEN '3 Years Sea Duty' WHEN 'E-5' THEN '6 Years Sea Duty' WHEN 'E-6' THEN '9 Years Sea Duty' WHEN 'E-7' THEN '9 Years Sea Duty' WHEN 'E-8' THEN '9 Years Sea Duty (Fleet Ops/NSE) or Field Duty' ELSE `p`.`required_duty` END WHEN `p`.`fos_rating` in (46,43,44,49) THEN CASE `p`.`rank_code` WHEN 'E-1' THEN 'None' WHEN 'E-2' THEN 'No Required Duty' WHEN 'E-3' THEN '18 Months Sea Duty' WHEN 'E-4' THEN '3 Years Field Duty' WHEN 'E-5' THEN '6 Years Field Duty' WHEN 'E-6' THEN '6 Years Field Duty' WHEN 'E-7' THEN '6 Years Field Duty' WHEN 'E-8' THEN '9 Years Sea Duty (Fleet Ops/NSE) or Field Duty' ELSE `p`.`required_duty` END WHEN `p`.`fos_rating` in (38,37,45) THEN CASE `p`.`rank_code` WHEN 'E-1' THEN 'None' WHEN 'E-2' THEN 'No Required Duty' WHEN 'E-3' THEN '18 Months Sea Duty' WHEN 'E-4' THEN '3 Years Field Duty' WHEN 'E-5' THEN '3 Years Field Duty' WHEN 'E-6' THEN '3 Years Field Duty' WHEN 'E-7' THEN '6 Years Field Duty' WHEN 'E-8' THEN '9 Years Sea Duty (Fleet Ops/NSE) or Field Duty' ELSE `p`.`required_duty` END ELSE `p`.`required_duty` END WHEN `p`.`date_enter_military_service` between '2016-12-02' and curdate() AND `p`.`fos_rating` in (38,37,45) THEN CASE `p`.`rank_code` WHEN 'E-1' THEN 'None' WHEN 'E-2' THEN '1 Years Field Duty' WHEN 'E-3' THEN '3 Years Field Duty' WHEN 'E-4' THEN '5 Years Field Duty' WHEN 'E-5' THEN '7 Years Field Duty' WHEN 'E-6' THEN '10 Years Field Duty' WHEN 'E-7' THEN '10 Years Field Duty' WHEN 'E-8' THEN '10 Years Field Duty' ELSE `p`.`required_duty` END WHEN `p`.`date_enter_military_service` < '1995-04-01' THEN CASE `p`.`rank_code` WHEN 'E-1' THEN 'None' WHEN 'E-2' THEN 'No Required Duty' WHEN 'E-3' THEN 'No Required Duty' WHEN 'E-4' THEN 'No Required Duty' WHEN 'E-5' THEN 'No Required Duty' WHEN 'E-6' THEN 'No Required Duty' WHEN 'E-7' THEN '3 Years Sea or Field Duty' WHEN 'E-8' THEN '6 Years Sea or Field Duty' ELSE `p`.`required_duty` END WHEN `p`.`date_enter_military_service` between '1995-04-01' and '2002-12-31' THEN CASE WHEN `p`.`fos_rating` in (2,3,4,5,23,24,25,26,27,28) THEN CASE `p`.`rank_code` WHEN 'E-1' THEN 'None' WHEN 'E-2' THEN '2 Years Sea Duty' WHEN 'E-3' THEN '3 Years Sea Duty' WHEN 'E-4' THEN '3 Years Sea Duty' WHEN 'E-5' THEN '6 Years Sea Duty' WHEN 'E-6' THEN '6 Years Sea Duty' WHEN 'E-7' THEN '9 Years Sea Duty' WHEN 'E-8' THEN '9 Years Sea Duty (Fleet Ops/NSE) or Field Duty' ELSE `p`.`required_duty` END WHEN `p`.`fos_rating` in (46,43,44,49) THEN CASE `p`.`rank_code` WHEN 'E-1' THEN 'None' WHEN 'E-2' THEN '6 Years Sea Duty' WHEN 'E-3' THEN '6 Years Sea Duty' WHEN 'E-4' THEN '6 Years Sea Duty' WHEN 'E-5' THEN '6 Years Sea Duty' WHEN 'E-6' THEN '6 Years Sea Duty' WHEN 'E-7' THEN '9 Years Sea Duty' WHEN 'E-8' THEN '9 Years Sea Duty (Fleet Ops/NSE) or Field Duty' ELSE `p`.`required_duty` END WHEN `p`.`fos_rating` in (38,37,45) THEN CASE `p`.`rank_code` WHEN 'E-1' THEN 'None' WHEN 'E-2' THEN '1 Years Sea Duty' WHEN 'E-3' THEN '3 Years Sea Duty' WHEN 'E-4' THEN '3 Years Sea Duty' WHEN 'E-5' THEN '3 Years Sea Duty' WHEN 'E-6' THEN '3 Years Sea Duty' WHEN 'E-7' THEN '9 Years Sea Duty' WHEN 'E-8' THEN '9 Years Sea Duty (Fleet Ops/NSE) or Field Duty' ELSE `p`.`required_duty` END ELSE `p`.`required_duty` END ELSE `p`.`required_duty` END AS `required_duty_calculated` FROM (((`personal_information_tbl` `p` left join `retirement_requests_tbl` `r` on(`p`.`id` = `r`.`personnel_id`)) left join (select `a`.`afpsn` AS `afpsn`,`a`.`unit` AS `unit`,`a`.`date_assume_billet` AS `date_assume_billet` from (`assignment_tbl` `a` join (select `assignment_tbl`.`afpsn` AS `afpsn`,max(`assignment_tbl`.`date_assume_billet`) AS `latest_date` from `assignment_tbl` where `assignment_tbl`.`date_assume_billet` <= curdate() group by `assignment_tbl`.`afpsn`) `latest` on(`a`.`afpsn` = `latest`.`afpsn` and `a`.`date_assume_billet` = `latest`.`latest_date`))) `latest_assign` on(`p`.`id` = `latest_assign`.`afpsn`)) left join (select `assignment_tbl`.`afpsn` AS `afpsn`,count(distinct lcase(trim(`assignment_tbl`.`designation`))) AS `designation_count`,max(`assignment_tbl`.`designation`) AS `designation` from `assignment_tbl` group by `assignment_tbl`.`afpsn`) `designation_counts` on(`p`.`id` = `designation_counts`.`afpsn`)) ;

