--
-- Structure for view `view_duration_assignment_tbl`
--
DROP TABLE IF EXISTS `view_duration_assignment_tbl`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `view_duration_assignment_tbl`  AS SELECT `a`.`afpsn` AS `afpsn`, sum(case when `a`.`field_duty_status` = 'GEOGRAPHICAL DUTY ASSIGNMENT' then ifnull(to_days(`a`.`date_relieve`) - to_days(`a`.`date_assume_billet`),to_days(curdate()) - to_days(`a`.`date_assume_billet`)) else 0 end) AS `total_field_duty_days`, concat(timestampdiff(YEAR,'2000-01-01','2000-01-01' + interval sum(case when `a`.`field_duty_status` = 'GEOGRAPHICAL DUTY ASSIGNMENT' then ifnull(to_days(`a`.`date_relieve`) - to_days(`a`.`date_assume_billet`),to_days(curdate()) - to_days(`a`.`date_assume_billet`)) else 0 end) day),' year(s), ',timestampdiff(MONTH,'2000-01-01' + interval timestampdiff(YEAR,'2000-01-01','2000-01-01' + interval sum(case when `a`.`field_duty_status` = 'GEOGRAPHICAL DUTY ASSIGNMENT' then ifnull(to_days(`a`.`date_relieve`) - to_days(`a`.`date_assume_billet`),to_days(curdate()) - to_days(`a`.`date_assume_billet`)) else 0 end) day) year,'2000-01-01' + interval sum(case when `a`.`field_duty_status` = 'GEOGRAPHICAL DUTY ASSIGNMENT' then ifnull(to_days(`a`.`date_relieve`) - to_days(`a`.`date_assume_billet`),to_days(curdate()) - to_days(`a`.`date_assume_billet`)) else 0 end) day) MOD 12,' month(s), ',to_days('2000-01-01' + interval sum(case when `a`.`field_duty_status` = 'GEOGRAPHICAL DUTY ASSIGNMENT' then ifnull(to_days(`a`.`date_relieve`) - to_days(`a`.`date_assume_billet`),to_days(curdate()) - to_days(`a`.`date_assume_billet`)) else 0 end) day) - to_days('2000-01-01' + interval timestampdiff(YEAR,'2000-01-01','2000-01-01' + interval sum(case when `a`.`field_duty_status` = 'GEOGRAPHICAL DUTY ASSIGNMENT' then ifnull(to_days(`a`.`date_relieve`) - to_days(`a`.`date_assume_billet`),to_days(curdate()) - to_days(`a`.`date_assume_billet`)) else 0 end) day) year + interval timestampdiff(MONTH,'2000-01-01' + interval timestampdiff(YEAR,'2000-01-01','2000-01-01' + interval sum(case when `a`.`field_duty_status` = 'GEOGRAPHICAL DUTY ASSIGNMENT' then ifnull(to_days(`a`.`date_relieve`) - to_days(`a`.`date_assume_billet`),to_days(curdate()) - to_days(`a`.`date_assume_billet`)) else 0 end) day) year,'2000-01-01' + interval sum(case when `a`.`field_duty_status` = 'GEOGRAPHICAL DUTY ASSIGNMENT' then ifnull(to_days(`a`.`date_relieve`) - to_days(`a`.`date_assume_billet`),to_days(curdate()) - to_days(`a`.`date_assume_billet`)) else 0 end) day) month),' day(s)') AS `field_duty`, sum(case when `a`.`field_duty_status` = 'SEA DUTY' then ifnull(to_days(`a`.`date_relieve`) - to_days(`a`.`date_assume_billet`),to_days(curdate()) - to_days(`a`.`date_assume_billet`)) else 0 end) AS `total_sea_duty_days`, concat(timestampdiff(YEAR,'2000-01-01','2000-01-01' + interval sum(case when `a`.`field_duty_status` = 'SEA DUTY' then ifnull(to_days(`a`.`date_relieve`) - to_days(`a`.`date_assume_billet`),to_days(curdate()) - to_days(`a`.`date_assume_billet`)) else 0 end) day),' year(s), ',timestampdiff(MONTH,'2000-01-01' + interval timestampdiff(YEAR,'2000-01-01','2000-01-01' + interval sum(case when `a`.`field_duty_status` = 'SEA DUTY' then ifnull(to_days(`a`.`date_relieve`) - to_days(`a`.`date_assume_billet`),to_days(curdate()) - to_days(`a`.`date_assume_billet`)) else 0 end) day) year,'2000-01-01' + interval sum(case when `a`.`field_duty_status` = 'SEA DUTY' then ifnull(to_days(`a`.`date_relieve`) - to_days(`a`.`date_assume_billet`),to_days(curdate()) - to_days(`a`.`date_assume_billet`)) else 0 end) day) MOD 12,' month(s), ',to_days('2000-01-01' + interval sum(case when `a`.`field_duty_status` = 'SEA DUTY' then ifnull(to_days(`a`.`date_relieve`) - to_days(`a`.`date_assume_billet`),to_days(curdate()) - to_days(`a`.`date_assume_billet`)) else 0 end) day) - to_days('2000-01-01' + interval timestampdiff(YEAR,'2000-01-01','2000-01-01' + interval sum(case when `a`.`field_duty_status` = 'SEA DUTY' then ifnull(to_days(`a`.`date_relieve`) - to_days(`a`.`date_assume_billet`),to_days(curdate()) - to_days(`a`.`date_assume_billet`)) else 0 end) day) year + interval timestampdiff(MONTH,'2000-01-01' + interval timestampdiff(YEAR,'2000-01-01','2000-01-01' + interval sum(case when `a`.`field_duty_status` = 'SEA DUTY' then ifnull(to_days(`a`.`date_relieve`) - to_days(`a`.`date_assume_billet`),to_days(curdate()) - to_days(`a`.`date_assume_billet`)) else 0 end) day) year,'2000-01-01' + interval sum(case when `a`.`field_duty_status` = 'SEA DUTY' then ifnull(to_days(`a`.`date_relieve`) - to_days(`a`.`date_assume_billet`),to_days(curdate()) - to_days(`a`.`date_assume_billet`)) else 0 end) day) month),' day(s)') AS `sea_duty`, sum(case when `a`.`field_duty_status` = 'COMBAT DUTY' then ifnull(to_days(`a`.`date_relieve`) - to_days(`a`.`date_assume_billet`),to_days(curdate()) - to_days(`a`.`date_assume_billet`)) else 0 end) AS `total_combat_duty_days`, concat(timestampdiff(YEAR,'2000-01-01','2000-01-01' + interval sum(case when `a`.`field_duty_status` = 'COMBAT DUTY' then ifnull(to_days(`a`.`date_relieve`) - to_days(`a`.`date_assume_billet`),to_days(curdate()) - to_days(`a`.`date_assume_billet`)) else 0 end) day),' year(s), ',timestampdiff(MONTH,'2000-01-01' + interval timestampdiff(YEAR,'2000-01-01','2000-01-01' + interval sum(case when `a`.`field_duty_status` = 'COMBAT DUTY' then ifnull(to_days(`a`.`date_relieve`) - to_days(`a`.`date_assume_billet`),to_days(curdate()) - to_days(`a`.`date_assume_billet`)) else 0 end) day) year,'2000-01-01' + interval sum(case when `a`.`field_duty_status` = 'COMBAT DUTY' then ifnull(to_days(`a`.`date_relieve`) - to_days(`a`.`date_assume_billet`),to_days(curdate()) - to_days(`a`.`date_assume_billet`)) else 0 end) day) MOD 12,' month(s), ',to_days('2000-01-01' + interval sum(case when `a`.`field_duty_status` = 'COMBAT DUTY' then ifnull(to_days(`a`.`date_relieve`) - to_days(`a`.`date_assume_billet`),to_days(curdate()) - to_days(`a`.`date_assume_billet`)) else 0 end) day) - to_days('2000-01-01' + interval timestampdiff(YEAR,'2000-01-01','2000-01-01' + interval sum(case when `a`.`field_duty_status` = 'COMBAT DUTY' then ifnull(to_days(`a`.`date_relieve`) - to_days(`a`.`date_assume_billet`),to_days(curdate()) - to_days(`a`.`date_assume_billet`)) else 0 end) day) year + interval timestampdiff(MONTH,'2000-01-01' + interval timestampdiff(YEAR,'2000-01-01','2000-01-01' + interval sum(case when `a`.`field_duty_status` = 'COMBAT DUTY' then ifnull(to_days(`a`.`date_relieve`) - to_days(`a`.`date_assume_billet`),to_days(curdate()) - to_days(`a`.`date_assume_billet`)) else 0 end) day) year,'2000-01-01' + interval sum(case when `a`.`field_duty_status` = 'COMBAT DUTY' then ifnull(to_days(`a`.`date_relieve`) - to_days(`a`.`date_assume_billet`),to_days(curdate()) - to_days(`a`.`date_assume_billet`)) else 0 end) day) month),' day(s)') AS `combat_duty`, sum(case when `a`.`field_duty_status` = 'GARRISON DUTY' then ifnull(to_days(`a`.`date_relieve`) - to_days(`a`.`date_assume_billet`),to_days(curdate()) - to_days(`a`.`date_assume_billet`)) else 0 end) AS `total_garrison_duty_days`, concat(timestampdiff(YEAR,'2000-01-01','2000-01-01' + interval sum(case when `a`.`field_duty_status` = 'GARRISON DUTY' then ifnull(to_days(`a`.`date_relieve`) - to_days(`a`.`date_assume_billet`),to_days(curdate()) - to_days(`a`.`date_assume_billet`)) else 0 end) day),' year(s), ',timestampdiff(MONTH,'2000-01-01' + interval timestampdiff(YEAR,'2000-01-01','2000-01-01' + interval sum(case when `a`.`field_duty_status` = 'GARRISON DUTY' then ifnull(to_days(`a`.`date_relieve`) - to_days(`a`.`date_assume_billet`),to_days(curdate()) - to_days(`a`.`date_assume_billet`)) else 0 end) day) year,'2000-01-01' + interval sum(case when `a`.`field_duty_status` = 'GARRISON DUTY' then ifnull(to_days(`a`.`date_relieve`) - to_days(`a`.`date_assume_billet`),to_days(curdate()) - to_days(`a`.`date_assume_billet`)) else 0 end) day) MOD 12,' month(s), ',to_days('2000-01-01' + interval sum(case when `a`.`field_duty_status` = 'GARRISON DUTY' then ifnull(to_days(`a`.`date_relieve`) - to_days(`a`.`date_assume_billet`),to_days(curdate()) - to_days(`a`.`date_assume_billet`)) else 0 end) day) - to_days('2000-01-01' + interval timestampdiff(YEAR,'2000-01-01','2000-01-01' + interval sum(case when `a`.`field_duty_status` = 'GARRISON DUTY' then ifnull(to_days(`a`.`date_relieve`) - to_days(`a`.`date_assume_billet`),to_days(curdate()) - to_days(`a`.`date_assume_billet`)) else 0 end) day) year + interval timestampdiff(MONTH,'2000-01-01' + interval timestampdiff(YEAR,'2000-01-01','2000-01-01' + interval sum(case when `a`.`field_duty_status` = 'GARRISON DUTY' then ifnull(to_days(`a`.`date_relieve`) - to_days(`a`.`date_assume_billet`),to_days(curdate()) - to_days(`a`.`date_assume_billet`)) else 0 end) day) year,'2000-01-01' + interval sum(case when `a`.`field_duty_status` = 'GARRISON DUTY' then ifnull(to_days(`a`.`date_relieve`) - to_days(`a`.`date_assume_billet`),to_days(curdate()) - to_days(`a`.`date_assume_billet`)) else 0 end) day) month),' day(s)') AS `garrison_duty` FROM `assignment_tbl` AS `a` GROUP BY `a`.`afpsn` ;

