--
-- Structure for view `view_for_schooling`
--
DROP TABLE IF EXISTS `view_for_schooling`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `view_for_schooling`  AS SELECT DISTINCT `p`.`id` AS `id`, `p`.`id` AS `personnel_id`, `vcr`.`current_rank_code` AS `rank_code`, `vcr`.`current_permanent_rank` AS `rank`, `p`.`firstname` AS `firstname`, `p`.`lastname` AS `lastname`, `p`.`middlename` AS `middlename`, `p`.`extension` AS `extension`, `p`.`afpsn` AS `afpsn`, `ao`.`name` AS `encoder`, `bost`.`bos_name` AS `bos`, `vsp`.`computed_sorted_number` AS `sorted`, `st`.`specialization`select 1 from `military_schooling_tbl` `m` where `m`.`afpsn` = `p`.`id` and ucase(trim(`m`.`specialization_course`)) like '%AFPSMC%' limit 1) then 'DONE AFPSMC' collate utf8mb4_unicode_ci when exists(select 1 from `military_schooling_tbl` `m` where `m`.`afpsn` = `p`.`id` and ucase(trim(`m`.`specialization_course`)) like '%EPAAC%' limit 1) then 'DONE EPAAC' collate utf8mb4_unicode_ci when `vcr`.`current_rank_code` like 'E-7' and (exists(select 1 from `military_schooling_tbl` `m` where `m`.`afpsn` = `p`.`id` and ucase(trim(`m`.`specialization_course`)) like '%SMC%' limit 1) and exists(select 1 from `military_schooling_tbl` `m` where `m`.`afpsn` = `p`.`id` and ucase(trim(`m`.`specialization_course`)) like '%NEPISMC%' limit 1) or exists(select 1 from `military_schooling_tbl` `m` where `m`.`afpsn` = `p`.`id` and ucase(trim(`m`.`specialization_course`)) like '%APOLC%' limit 1)) then 'FOR AFPSMC' collate utf8mb4_unicode_ci when `vcr`.`current_rank_code` = 'E-5' and exists(select 1 from `military_schooling_tbl` `m` where `m`.`afpsn` = `p`.`id` and (ucase(trim(`m`.`specialization_course`)) like '%NEPISMC%' or ucase(trim(`m`.`specialization_course`)) like '%NEPIAC%') limit 1) then 'FOR SMC' collate utf8mb4_unicode_ci when `vcr`.`current_rank_code` like 'E-5' and exists(select 1 from `military_schooling_tbl` `m` where `m`.`afpsn` = `p`.`id` and (ucase(trim(`m`.`specialization_course`)) like '%NEPICASC%' or ucase(trim(`m`.`specialization_course`)) like '%NIIASC%' or ucase(trim(`m`.`specialization_course`)) like '%CTIASC%' or ucase(trim(`m`.`specialization_course`)) like '%CIASC%' or ucase(trim(`m`.`specialization_course`)) like '%NIRAASC%') limit 1) and exists(select 1 from `military_schooling_tbl` `m` where `m`.`afpsn` = `p`.`id` and ucase(trim(`m`.`specialization_course`)) like '%NEPBIC%' limit 1) then 'FOR NEPISMC SKILLS' collate utf8mb4_unicode_ci when `vcr`.`current_rank_code` like 'E-3' and (exists(select 1 from `military_schooling_tbl` `m` where `m`.`afpsn` = `p`.`id` and (ucase(trim(`m`.`specialization_course`)) like '%NEPICASC%' or ucase(trim(`m`.`specialization_course`)) like '%NIIASC%' or ucase(trim(`m`.`specialization_course`)) like '%CTIASC%' or ucase(trim(`m`.`specialization_course`)) like '%CIASC%' or ucase(trim(`m`.`specialization_course`)) like '%NIRAASC%') limit 1) and exists(select 1 from `military_schooling_tbl` `m` where `m`.`afpsn` = `p`.`id` and ucase(trim(`m`.`specialization_course`)) like '%NEPBIC%' limit 1) or exists(select 1 from `military_schooling_tbl` `m` where `m`.`afpsn` = `p`.`id` and ucase(trim(`m`.`specialization_course`)) like '%NEPIC%' limit 1)) then 'FOR ASC LEADERSHIP' collate utf8mb4_unicode_ci when `vcr`.`current_rank_code` = 'E-3' and exists(select 1 from `military_schooling_tbl` `m` where `m`.`afpsn` = `p`.`id` and ucase(trim(`m`.`specialization_course`)) like '%NEPBIC%' limit 1) and exists(select 1 from `military_schooling_tbl` `m` where `m`.`afpsn` = `p`.`id` and (ucase(trim(`m`.`specialization_course`)) like '%(BSC)%' or ucase(trim(`m`.`specialization_course`)) like '%SBC%') limit 1) then 'FOR ASC SKILLS' collate utf8mb4_unicode_ci when `vcr`.`current_rank_code` in ('E-1','E-2') and exists(select 1 from `military_schooling_tbl` `m` where `m`.`afpsn` = `p`.`id` and (ucase(trim(`m`.`specialization_course`)) like '%(BSC)%' or ucase(trim(`m`.`specialization_course`)) like '%SBC%') limit 1) then 'FOR NEPBIC' collate utf8mb4_unicode_ci when `vcr`.`current_rank_code` in ('E-1','E-2') and !exists(select 1 from `military_schooling_tbl` `m` where `m`.`afpsn` = `p`.`id` and (ucase(trim(`m`.`specialization_course`)) like '%(BSC)%' or ucase(trim(`m`.`specialization_course`)) like '%SBC%') limit 1) then 'FOR SBC' collate utf8mb4_unicode_ci else 'NO AVAILABLE SCHOOLING REMARKS' end AS `remarks` from (((((`personal_information_tbl` `p` left join `vw_personnel_current_rank` `vcr` on(`vcr`.`id` = `p`.`id`)) left join `specialization_tbl` `st` on(`st`.`personnel_id` = `p`.`id`)) left join `bos_tbl` `bost` on(`p`.`bos` = `bost`.`id`)) left join `account_offices` `ao` on(`ao`.`id` = `p`.`user_id`)) left join `view_sorted_personnel` `vsp` on(`vsp`.`personnel_id` = `p`.`id`)) where `p`.`status_definition_category` is null or `p`.`status_definition_category` not in ('resigned','retired','awol','discharge','disease')  ;

