--
-- Structure for view `view_midtermreenlistment`
--
DROP TABLE IF EXISTS `view_midtermreenlistment`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `view_midtermreenlistment`  AS SELECT `p`.`id` AS `personnel_id`, `vcr`.`current_rank_code` AS `rankcode`, `vcr`.`current_permanent_rank` AS `rank`, `p`.`firstname` AS `firstname`, `p`.`middlename` AS `middlename`, `p`.`lastname` AS `lastname`, `p`.`extension` AS `extension`, `p`.`afpsn` AS `afpsn`, `bos`.`bos_name` AS `bosname`, `ao`.`name` AS `encoder`, CASE WHEN `r`.`date_etad_sot_reenlisment` is null THEN 'Need to Encode Date of Enlistment' ELSE `r`.`date_etad_sot_reenlisment` END AS `dateofenlistment`, `vsp`.`computed_sorted_number` AS `sorted_number`, `r`.`date_etad_sot_reenlisment`+ interval 18 month AS `dateofmidtermenlistment`, CASE WHEN `vcr`.`current_rank_code` in ('E-1','O-1') THEN NULL ELSE `r`.`date_etad_sot_reenlisment`+ interval 54 month END AS `dateofmidtermreenlistment`, CASE WHEN `r`.`date_etad_sot_reenlisment` is null THEN 'INVALID DATE' WHEN `vcr`.`current_rank_code` = 'E-1' AND `r`.`date_etad_sot_reenlisment` + interval 18 month < curdate() AND abs(to_days(curdate()) - to_days(`r`.`date_etad_sot_reenlisment` + interval 18 month)) <= 600 THEN 'OK' WHEN `vcr`.`current_rank_code` not in ('E-1','O-1') AND `r`.`date_etad_sot_reenlisment` + interval 18 month < curdate() AND `r`.`date_etad_sot_reenlisment` + interval 54 month > curdate() THEN 'OK' WHEN `r`.`date_etad_sot_reenlisment` + interval 18 month < curdate() THEN 'NOT UPDATED' WHEN abs(to_days(curdate()) - to_days(`r`.`date_etad_sot_reenlisment` + interval 18 month)) <= 540 THEN 'OK' WHEN abs(to_days(curdate()) - to_days(`r`.`date_etad_sot_reenlisment` + interval 18 month)) <= 3650 THEN 'TOO FAR ON A CURRENT DATE PLEASE CHECK' ELSE 'POSSIBLY WRONG or NO ENCODE' END AS `reenlistmentstatus` FROM (((((`personal_information_tbl` `p` left join `vw_personnel_current_rank` `vcr` on(`vcr`.`id` = `p`.`id`)) left join `re_enlistment_tbl` `r` on(`r`.`id` = (select `r2`.`id` from `re_enlistment_tbl` `r2` where `r2`.`afpsn` = `p`.`id` order by abs(to_days(`r2`.`date_etad_sot_reenlisment`) - to_days(curdate())) limit 1))) left join `bos_tbl` `bos` on(`p`.`bos` = `bos`.`id`)) left join `account_offices` `ao` on(`p`.`user_id` = `ao`.`id`)) left join `view_sorted_personnel` `vsp` on(`vsp`.`id` = `p`.`id`)) WHERE coalesce(trim(`p`.`status_definition_category`),'') not in ('resigned','retired','awol','discharge','disease') ;

-- --------------------------------------------------------

--
-- Structure for view `view_personnel_current_assignment`
--
DROP TABLE IF EXISTS `view_personnel_current_assignment`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `view_personnel_current_assignment`  AS SELECT `a`.`afpsn` AS `afpsn`, concat_ws(' | ',`a`.`designation`,`a`.`branch`,`a`.`office`,`a`.`unit`) AS `current_assignment`, `a`.`date_assume_billet` AS `date_assume_billet` FROM (select `a`.`id` AS `id`,`a`.`afpsn` AS `afpsn`,`a`.`rank` AS `rank`,`a`.`unit` AS `unit`,`a`.`subunit` AS `subunit`,`a`.`othersubunit` AS `othersubunit`,`a`.`office` AS `office`,`a`.`branch` AS `branch`,`a`.`designation` AS `designation`,`a`.`types_of_assignment_units` AS `types_of_assignment_units`,`a`.`date_assume_billet` AS `date_assume_billet`,`a`.`date_relieve` AS `date_relieve`,`a`.`field_duty_status` AS `field_duty_status`,`a`.`date_created` AS `date_created`,row_number() over ( partition by `a`.`afpsn` order by `a`.`date_assume_billet` desc,`a`.`id` desc) AS `rn` from `assignment_tbl` `a` where `a`.`date_assume_billet` <= curdate()) AS `a` WHERE `a`.`rn` = 1 ;

-- --------------------------------------------------------

--
-- Structure for view `view_promotion_computation`
--
DROP TABLE IF EXISTS `view_promotion_computation`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `view_promotion_computation`  AS SELECT DISTINCT `p`.`id` AS `id`, `p`.`id` AS `personnel_id`, `vcr`.`current_permanent_rank` AS `rank`, `p`.`firstname` AS `firstname`, `p`.`lastname` AS `lastname`, `p`.`middlename` AS `middlename`, `p`.`extension` AS `extension`, `p`.`afpsn` AS `afpsn`, `bost`.`bos_name` AS `bos`, `ao`.`name` AS `encoder`, `vcr`.`current_rank_code` AS `rank_code`, CASE WHEN nullif(trim(`r`.`date_etad_sot_reenlisment`),'') is null THEN 'Need to Encode latest Reenlistment' ELSE `r`.`date_etad_sot_reenlisment` END AS `base_reenlistment_date`, CASE WHEN nullif(trim(`pr`.`date_promoted`),'') is null THEN 'Need to Encode latest Promotion' ELSE `pr`.`date_promoted` END AS `base_promotion_date`, CASE WHEN `vcr`.`current_rank_code` like 'O-%' THEN 'No Computation' WHEN `vcr`.`current_rank_code` = 'E-1' THEN `r`.`date_etad_sot_reenlisment`+ interval 18 month WHEN `vcr`.`current_rank_code` in ('E-2','E-3') THEN `pr`.`date_promoted`+ interval 2 year WHEN `vcr`.`current_rank_code` = 'E-4' THEN `pr`.`date_promoted`+ interval 3 year WHEN `vcr`.`current_rank_code` in ('E-5','E-6') THEN `pr`.`date_promoted`+ interval 48 month WHEN `vcr`.`current_rank_code` = 'E-7' THEN `pr`.`date_promoted`+ interval 60 month ELSE NULL END AS `submissionofpromotion`, CASE WHEN `vcr`.`current_rank_code` like 'O-%' THEN 'No Computation' WHEN `vcr`.`current_rank_code` = 'E-1' THEN `r`.`date_etad_sot_reenlisment`+ interval 36 month WHEN `vcr`.`current_rank_code` in ('E-2','E-3') THEN `pr`.`date_promoted`+ interval 36 month WHEN `vcr`.`current_rank_code` = 'E-4' THEN `pr`.`date_promoted`+ interval 48 month WHEN `vcr`.`current_rank_code` in ('E-5','E-6') THEN `pr`.`date_promoted`+ interval 60 month WHEN `vcr`.`current_rank_code` = 'E-7' THEN `pr`.`date_promoted`+ interval 72 month WHEN `vcr`.`current_rank_code` = 'E-8' THEN `pr`.`date_promoted`+ interval 36 month ELSE NULL END AS `timeingrade`, CASE WHEN `vcr`.`current_rank_code` like 'O-%' THEN 'No Computation' WHEN `vcr`.`current_rank_code` = 'E-1' THEN `r`.`date_etad_sot_reenlisment`+ interval 4 year WHEN `vcr`.`current_rank_code` = 'E-2' THEN `pr`.`date_promoted`+ interval 48 month WHEN `vcr`.`current_rank_code` = 'E-3' THEN `pr`.`date_promoted`+ interval 60 month WHEN `vcr`.`current_rank_code` = 'E-4' THEN `pr`.`date_promoted`+ interval 72 month WHEN `vcr`.`current_rank_code` in ('E-5','E-6') THEN `pr`.`date_promoted`+ interval 84 month WHEN `vcr`.`current_rank_code` = 'E-7' THEN `pr`.`date_promoted`+ interval 96 month WHEN `vcr`.`current_rank_code` = 'E-8' THEN `pr`.`date_promoted`+ interval 60 month WHEN `vcr`.`current_rank_code` = 'E-9' THEN `pr`.`date_promoted`+ interval 48 month ELSE NULL END AS `tenureingrade`, CASE WHEN `vcr`.`current_rank_code` like 'O-%' THEN 'No Computation' WHEN `vcr`.`current_rank_code` in ('E-2','E-3') THEN `pr`.`date_promoted`+ interval 18 month WHEN `vcr`.`current_rank_code` = 'E-4' THEN `pr`.`date_promoted`+ interval 24 month WHEN `vcr`.`current_rank_code` in ('E-5','E-6') THEN `pr`.`date_promoted`+ interval 30 month WHEN `vcr`.`current_rank_code` = 'E-7' THEN `pr`.`date_promoted`+ interval 36 month ELSE NULL END AS `due_for_promex_exam` FROM (((((`personal_information_tbl` `p` left join `vw_personnel_current_rank` `vcr` on(`vcr`.`id` = `p`.`id`)) left join `account_offices` `ao` on(`ao`.`id` = `p`.`user_id`)) left join `re_enlistment_tbl` `r` on(`r`.`afpsn` = `p`.`id` and `r`.`date_etad_sot_reenlisment` = (select `rr`.`date_etad_sot_reenlisment` from `re_enlistment_tbl` `rr` where `rr`.`afpsn` = `p`.`id` order by abs(to_days(curdate()) - to_days(`rr`.`date_etad_sot_reenlisment`)) limit 1))) left join `promotion_tbl` `pr` on(`pr`.`afpsn` = `p`.`id` and `pr`.`date_promoted` = (select `pp`.`date_promoted` from `promotion_tbl` `pp` where `pp`.`afpsn` = `p`.`id` order by abs(to_days(curdate()) - to_days(`pp`.`date_promoted`)) limit 1))) left join `bos_tbl` `bost` on(`p`.`bos` = `bost`.`id`)) WHERE `vcr`.`current_rank_code` like 'O-%' OR coalesce(trim(`p`.`status_definition_category`),'') not in ('resigned','retired','awol','discharge','disease') ;

