--
-- Structure for view `view_sorted_personnel`
--
DROP TABLE IF EXISTS `view_sorted_personnel`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `view_sorted_personnel`  AS SELECT DISTINCT `p`.`id` AS `id`, `p`.`id` AS `personnel_id`, `p`.`afpsn` AS `afpsn`, row_number() over ( order by case when `vcr`.`current_rank_code` like 'O-%' then 0 when `vcr`.`current_rank_code` like 'E-%' then 1 else 2 end,case when `vcr`.`current_rank_code` like 'O-%' then cast(substring_index(`vcr`.`current_rank_code`,'-',-1) as unsigned) when `vcr`.`current_rank_code` like 'E-%' then cast(substring_index(`vcr`.`current_rank_code`,'-',-1) as unsigned) else 999999 end desc,case when `p`.`afpsn` like 'O-%' then cast(substr(`p`.`afpsn`,3) as unsigned) else cast(`p`.`afpsn` as unsigned) end) AS `computed_sorted_number` FROM (`personal_information_tbl` `p` left join `vw_personnel_current_rank` `vcr` on(`vcr`.`id` = `p`.`id`)) ;

