--
-- Structure for view `vw_list_personal_information`
--
DROP TABLE IF EXISTS `vw_list_personal_information`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vw_list_personal_information`  AS SELECT DISTINCT `pi`.`id` AS `id`, `pi`.`user_id` AS `user_id`, `vcr`.`current_rank_code` AS `rank_code`, `vcr`.`current_permanent_rank` AS `rank`, `ao`.`name` AS `office`, `pi`.`lastname` AS `lastname`, `pi`.`firstname` AS `firstname`, `pi`.`middlename` AS `middlename`, `pi`.`extension` AS `extension`, `pi`.`afpsn` AS `afpsn`, `bt`.`bos_name` AS `bos`, `vpca`.`current_assignment` AS `current_assignment`, `vpca`.`date_assume_billet` AS `date_current_assignment`, `g`.`gender_name` AS `gender`, `pi`.`birthdate` AS `birthdate`, `pi`.`source_comms` AS `source_comms`, `pi`.`class` AS `class`, `frt`.`fos_rating_name` AS `fos_rating`, `pi`.`authority` AS `authority`, `pi`.`mobile_number` AS `mobile_number`, `pi`.`date_enter_military_service` AS `date_enter_military_service`, CASE WHEN `vcr`.`current_rank_code` in ('E-1','O-1') THEN (select `vpr`.`transaction_date` from `vw_personnel_promotion_reenlistment` `vpr` where `vpr`.`personnel_id` = `pi`.`id` and `vpr`.`transaction_type` = 'RE_ENLISTMENT' and `vpr`.`transaction_date` <= current_timestamp() order by `vpr`.`transaction_date` desc limit 1) + interval 3 year WHEN `vcr`.`current_rank_code` like 'E-%' AND cast(substr(`vcr`.`current_rank_code`,3) as unsigned) >= 2 THEN (select max(`vpr`.`transaction_date`) from `vw_personnel_promotion_reenlistment` `vpr` where `vpr`.`personnel_id` = `pi`.`id` and `vpr`.`transaction_type` = 'PROMOTION' and `vpr`.`transaction_date` <= current_timestamp()) + interval 6 year WHEN `vcr`.`current_rank_code` like 'O-%' AND cast(substr(`vcr`.`current_rank_code`,3) as unsigned) >= 2 THEN (select max(`vpr`.`transaction_date`) from `vw_personnel_promotion_reenlistment` `vpr` where `vpr`.`personnel_id` = `pi`.`id` and `vpr`.`transaction_type` = 'PROMOTION' and `vpr`.`transaction_date` <= current_timestamp()) + interval 6 year ELSE NULL END AS `etad_ete`, `pi`.`birthdate`+ interval 57 year AS `compulsory`, CASE WHEN left(`pi`.`mobile_number`,4) in ('0905','0906','0915','0916','0917','0926','0927','0935','0936','0937','0945','0955','0956','0965','0966','0967','0975','0977','0978','0979','0994','0995','0996','0997') THEN 'Globe/TM' WHEN left(`pi`.`mobile_number`,4) in ('0907','0908','0909','0910','0911','0912','0913','0914','0918','0919','0920','0921','0928','0929','0930','0938','0939','0946','0947','0948','0949','0950','0951','0961','0963','0968','0969','0981','0989','0998','0999') THEN 'Smart/TNT' WHEN left(`pi`.`mobile_number`,4) in ('0922','0923','0924','0925','0931','0932','0933','0934','0940','0941','0942','0943','0944') THEN 'DITO' ELSE 'Unknown' END AS `service_provider`, `pi`.`email_address` AS `email_address`, `cst`.`civil_status_name` AS `civil_status`, `btt`.`blood_type_name` AS `blood_type`, `ppt`.`physical_profile_name` AS `physical_profile`, `pi`.`ethnicity` AS `ethnicity`, `pi`.`religion` AS `religion`, `sclt`.`security_clearance_level_name` AS `security_level`, `vdat`.`field_duty` AS `field_duty`, `vdat`.`sea_duty` AS `sea_duty`, `vdat`.`combat_duty` AS `combat_duty`, `vdat`.`garrison_duty` AS `garrison_duty`, `vfs`.`remarks` AS `schooling_remarks`, `vpc`.`base_reenlistment_date` AS `updated_reenlistment`, `vpc`.`base_promotion_date` AS `updated_promotion`, `vpc`.`submissionofpromotion` AS `start_submission_promotion`, `vpc`.`timeingrade` AS `time_in_grade`, `vpc`.`tenureingrade` AS `tenure_in_grade`, `vpc`.`due_for_promex_exam` AS `for_promex_exam`, `vmr`.`dateofmidtermenlistment` AS `dateofmidtermenlistment`, `vmr`.`dateofmidtermreenlistment` AS `dateofmidtermreenlistment`, `vsp`.`computed_sorted_number` AS `sorted_number` FROM (((((((((((((((`personal_information_tbl` `pi` left join `vw_personnel_current_rank` `vcr` on(`vcr`.`id` = `pi`.`id`)) left join `account_offices` `ao` on(`pi`.`user_id` = `ao`.`id`)) left join `gender_tbl` `g` on(`g`.`id` = `pi`.`sex`)) left join `fos_rating_tbl` `frt` on(`frt`.`id` = `pi`.`fos_rating`)) left join `civil_status_tbl` `cst` on(`cst`.`id` = `pi`.`civil_status`)) left join `blood_type_tbl` `btt` on(`btt`.`id` = `pi`.`blood_type`)) left join `physical_profile_tbl` `ppt` on(`ppt`.`id` = `pi`.`physical_profile`)) left join `security_clearance_level_tbl` `sclt` on(`sclt`.`id` = `pi`.`security_level`)) left join `view_duration_assignment_tbl` `vdat` on(`vdat`.`afpsn` = `pi`.`id`)) left join `view_for_schooling` `vfs` on(`vfs`.`id` = `pi`.`id`)) left join `view_promotion_computation` `vpc` on(`vpc`.`id` = `pi`.`id`)) left join `bos_tbl` `bt` on(`pi`.`bos` = `bt`.`id`)) left join `view_personnel_current_assignment` `vpca` on(`pi`.`id` = `vpca`.`afpsn`)) left join `view_midtermreenlistment` `vmr` on(`pi`.`id` = `vmr`.`personnel_id`)) left join `view_sorted_personnel` `vsp` on(`pi`.`id` = `vsp`.`id`)) WHERE coalesce(trim(`pi`.`status_definition_category`),'') not in ('resigned','retired','awol','discharge','disease','change fosrating') ORDER BY `vsp`.`computed_sorted_number` ASC ;

