DROP TABLE IF EXISTS `vw_list_personal_information_v2`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vw_list_personal_information_v2`  AS SELECT `pi`.`id` AS `id`, `pi`.`user_id` AS `user_id`, `vcr`.`current_rank_code` AS `rank_code`, `vcr`.`current_permanent_rank` AS `rank`, `ao`.`name` AS `office`, `pi`.`lastname` AS `lastname`, `pi`.`firstname` AS `firstname`, `pi`.`middlename` AS `middlename`, `pi`.`extension` AS `extension`, `pi`.`afpsn` AS `afpsn`, `bt`.`bos_name` AS `bos`, `vpca`.`current_assignment` AS `current_assignment`, `vpca`.`date_assume_billet` AS `date_current_assignment`, `vsp`.`computed_sorted_number` AS `sorted_number` FROM (((((`personal_information_tbl` `pi` left join `vw_personnel_current_rank` `vcr` on(`vcr`.`id` = `pi`.`id`)) left join `account_offices` `ao` on(`ao`.`id` = `pi`.`user_id`)) left join `bos_tbl` `bt` on(`bt`.`id` = `pi`.`bos`)) left join `view_personnel_current_assignment` `vpca` on(`vpca`.`afpsn` = `pi`.`id`)) left join `view_sorted_personnel` `vsp` on(`vsp`.`id` = `pi`.`id`)) WHERE coalesce(trim(`pi`.`status_definition_category`),'') not in ('resigned','retired','awol','discharge','disease','change fosrating') ORDER BY `vsp`.`computed_sorted_number` ASC ;

