--
-- Structure for view `vw_personnel_current_rank`
--
DROP TABLE IF EXISTS `vw_personnel_current_rank`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vw_personnel_current_rank`  AS SELECT `p`.`id` AS `id`, `p`.`afpsn` AS `afpsn`, coalesce(`v`.`permanent_rank`,'Encode Promotion or Enlistment') AS `current_permanent_rank`, coalesce(`r`.`rank_code`,'Encode Promotion or Enlistment') AS `current_rank_code` FROM (((`personal_information_tbl` `p` left join (select `x`.`personnel_id` AS `personnel_id`,`x`.`permanent_rank` AS `permanent_rank`,`x`.`transaction_date` AS `transaction_date` from (select `v`.`personnel_id` AS `personnel_id`,`v`.`afpsn` AS `afpsn`,`v`.`transaction_type` AS `transaction_type`,`v`.`category` AS `category`,`v`.`transaction_date` AS `transaction_date`,`v`.`special_order` AS `special_order`,`v`.`permanent_rank` AS `permanent_rank`,row_number() over ( partition by `v`.`personnel_id` order by `v`.`transaction_date` desc) AS `rn` from `vw_personnel_promotion_reenlistment` `v` where `v`.`transaction_date` <= curdate()) `x` where `x`.`rn` = 1) `v` on(`v`.`personnel_id` = `p`.`id`)) left join `rank_tbl` `r` on(`r`.`rank_name` = `v`.`permanent_rank`)) left join `bos_tbl` `bt` on(`p`.`bos` = `bt`.`id`)) ;

-- --------------------------------------------------------

--
-- Structure for view `vw_personnel_promotion_reenlistment`
--
DROP TABLE IF EXISTS `vw_personnel_promotion_reenlistment`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vw_personnel_promotion_reenlistment`  AS SELECT row_number() over ( order by `career_history`.`personnel_id`,`career_history`.`transaction_date` desc) AS `id`, `career_history`.`source_id` AS `source_id`, `career_history`.`personnel_id` AS `personnel_id`, `career_history`.`afpsn` AS `afpsn`, `career_history`.`transaction_type` AS `transaction_type`, `career_history`.`category` AS `category`, `career_history`.`transaction_date` AS `transaction_date`, `career_history`.`special_order` AS `special_order`, `career_history`.`permanent_rank` AS `permanent_rank` FROM (select `pr`.`id` AS `source_id`,`p`.`id` AS `personnel_id`,`p`.`afpsn` AS `afpsn`,'PROMOTION' AS `transaction_type`,`pr`.`promotion_category` AS `category`,`pr`.`date_promoted` AS `transaction_date`,`pr`.`special_order` AS `special_order`,`pr`.`permanent_rank` AS `permanent_rank` from (`personal_information_tbl` `p` left join `promotion_tbl` `pr` on(`p`.`id` = `pr`.`afpsn`)) union all select `re`.`id` AS `source_id`,`p`.`id` AS `personnel_id`,`p`.`afpsn` AS `afpsn`,'RE_ENLISTMENT' AS `transaction_type`,`re`.`military_service_category` AS `category`,`re`.`date_etad_sot_reenlisment` AS `transaction_date`,`re`.`special_order` AS `special_order`,`re`.`rank` AS `permanent_rank` from (`personal_information_tbl` `p` left join `re_enlistment_tbl` `re` on(`p`.`id` = `re`.`afpsn`))) AS `career_history` WHERE `career_history`.`source_id` is not null ORDER BY `career_history`.`personnel_id` ASC, `career_history`.`transaction_date` DESC ;

