--
-- Structure for view `vw_status_definition_category_count`
--
DROP TABLE IF EXISTS `vw_status_definition_category_count`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vw_status_definition_category_count`  AS SELECT 1 AS `id`, sum(case when lcase(trim(`p`.`status_definition_category`)) in ('active','relieved') then 1 else 0 end) AS `active`, sum(case when lcase(trim(`p`.`status_definition_category`)) in ('active','relieved') and trim(`p`.`afpsn`)  not like 'O-%' then 1 else 0 end) AS `active_enlisted`, sum(case when lcase(trim(`p`.`status_definition_category`)) in ('active','relieved') and trim(`p`.`afpsn`) like 'O-%' then 1 else 0 end) AS `active_officer`, sum(case when lcase(trim(`p`.`status_definition_category`)) = 'awol' then 1 else 0 end) AS `awol`, sum(case when lcase(trim(`p`.`status_definition_category`)) = 'change fosrating' then 1 else 0 end) AS `change_fosrating`, sum(case when lcase(trim(`p`.`status_definition_category`)) = 'discharge' then 1 else 0 end) AS `discharge`, sum(case when lcase(trim(`p`.`status_definition_category`)) = 'disease' then 1 else 0 end) AS `disease`, sum(case when lcase(trim(`p`.`status_definition_category`)) = 'due for retirement' then 1 else 0 end) AS `due_for_retirement`, sum(case when lcase(trim(`p`.`status_definition_category`)) = 'relieved' then 1 else 0 end) AS `relieved`, sum(case when lcase(trim(`p`.`status_definition_category`)) = 'resigned' then 1 else 0 end) AS `resigned`, sum(case when lcase(trim(`p`.`status_definition_category`)) = 'retired' then 1 else 0 end) AS `retired` FROM `personal_information_tbl` AS `p` ;

